const formatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Phoenix',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
});

const parts = formatter.formatToParts(new Date());
const year = parts.find(p => p.type === 'year').value;
const month = parts.find(p => p.type === 'month').value;
const day = parts.find(p => p.type === 'day').value;

const date = `${year}-${month}-${day}`;

return [{
  json: {
    timezone: 'America/Phoenix',
    date
  }
}];

const data = $json.data;

// Extract each data source from the Aggregate output
const dateItem    = data.find(d => d.date      !== undefined);
const rosterItem  = data.find(d => d.members   !== undefined);
const clientsItem = data.find(d => d.customers !== undefined);
const shiftItem   = data.find(d => d.shifts    !== undefined);

const date = dateItem.date;

// Determine day of week for the Arizona date string
const dayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const dayOfWeek = dayNames[new Date(`${date}T12:00:00Z`).getDay()];

// Convert Arizona HH:MM (UTC-7, no DST) to a UTC ISO datetime string.
// nextDay=true when the endpoint crosses into the following AZ calendar day.
function azToUTC(azHHMM, baseDate, nextDay = false) {
  const [h, m] = azHHMM.split(':').map(Number);
  const utcH = h + 7;
  const d = new Date(`${baseDate}T00:00:00Z`);
  if (nextDay) d.setUTCDate(d.getUTCDate() + 1);
  d.setUTCHours(utcH % 24, m, 0, 0);
  if (utcH >= 24) d.setUTCDate(d.getUTCDate() + 1);
  return d.toISOString().replace('.000Z', 'Z');
}

// Map member ID → their shift
const memberShiftMap = {};
for (const shift of shiftItem.shifts) {
  for (const sm of shift.members) {
    memberShiftMap[sm.memberId] = shift;
  }
}

// Members scheduled to work today
const workingMembers = rosterItem.members.filter(m =>
  m.active && m.days.includes(dayOfWeek)
);

const customers       = clientsItem.customers;
const hoursPerCustomer = parseFloat((8 / customers.length).toFixed(4));

const entries = [];

for (const member of workingMembers) {
  const shift = memberShiftMap[member.memberId];

  // Resolve shift window in UTC; overnight = shift ends before it starts (e.g. "00:00" < "14:00")
  let timeStart, timeEnd;
  if (shift) {
    const overnight = shift.end < shift.start;
    timeStart = azToUTC(shift.start, date);
    timeEnd   = azToUTC(shift.end,   date, overnight);
  } else {
    timeStart = `${date}T15:00:00Z`;
    timeEnd   = `${date}T23:00:00Z`;
  }

  // Billable entries: one per customer at an equal share of 8 hours
  for (const customer of customers) {
    entries.push({
      json: {
        body: {
          company:        { id: customer.companyId },
          chargeToType:   rosterItem.chargeToType,
          chargeToId:     rosterItem.chargeToId,
          member:         { id: member.memberId },
          locationId:     rosterItem.locationId,
          businessUnitId: rosterItem.businessUnitId,
          workType:       { id: rosterItem.workTypeId },
          workRole:       { id: member.workRoleId },
          timeStart,
          timeEnd,
          actualHours:    hoursPerCustomer,
          billableOption: 'Billable',
          addToDetailDescriptionFlag: false,
          addToInternalAnalysisFlag:  false,
          addToResolutionFlag:        false
        }
      }
    });
  }

  // Non-billable admin entry: 2 hours immediately after the shift
  const adminEnd = (() => {
    const d = new Date(timeEnd);
    d.setUTCHours(d.getUTCHours() + 2);
    return d.toISOString().replace('.000Z', 'Z');
  })();

  entries.push({
    json: {
      body: {
        company:        { id: rosterItem.companyId },
        chargeToType:   rosterItem.chargeToType,
        chargeToId:     rosterItem.chargeToId,
        member:         { id: member.memberId },
        locationId:     rosterItem.locationId,
        businessUnitId: rosterItem.businessUnitId,
        workType:       { id: rosterItem.workTypeId },
        workRole:       { id: member.workRoleId },
        timeStart:      timeEnd,
        timeEnd:        adminEnd,
        actualHours:    2,
        billableOption: 'DoNotBill',
        addToDetailDescriptionFlag: false,
        addToInternalAnalysisFlag:  false,
        addToResolutionFlag:        false
      }
    }
  });
}

return entries;

